package io.imiocode.team.tool;
import com.fasterxml.jackson.databind.node.ObjectNode;import io.imiocode.team.model.TeamPrincipal;import io.imiocode.team.task.TeamTaskService;import io.imiocode.tool.*;import java.util.function.Supplier;
public final class TaskStopTool extends AbstractTaskTool {public TaskStopTool(TeamTaskService t,Supplier<TeamPrincipal> p,ToolLimits l,SecretRedactor r){super(def(),t,p,l,r);}private static ToolDefinition def(){ObjectNode s=schema();s.withObject("properties").putObject("task_id").put("type","string");s.putArray("required").add("task_id");return new ToolDefinition("TaskStop","停止团队任务及其活动负责人。",s,ToolRisk.MEDIUM);}@Override protected ToolResult executeValidated(ObjectNode a){rejectUnknownFields(a,"task_id");return json(tasks.stop(principal(),requireText(a,"task_id")));}}
